fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Put values into a vector and find the maximum target
    let mut vals = [a, b, c];
    let max_val = *vals.iter().max().unwrap();

    // Calculate the differences needed to reach max_val for each integer
    let diffs: Vec<i8> = vals.iter().map(|&x| max_val - x).collect();

    // Sum of all differences
    let sum: i8 = diffs.iter().sum();

    // The idea:
    // We want to cover all increments (sum) with minimum operations.
    // - Operation 1 adds +2 to one integer (covers 2 increments in 1 op)
    // - Operation 2 adds +1 to two integers (covers 2 increments in 1 op as well)
    //
    // Both operations are effectively "2 increments per operation".
    // So ideally, minimum operations is at least sum/2 rounded up.
    //
    // But we must check parity:
    // If sum is even, answer = sum / 2
    // If sum is odd, answer = (sum / 2) + 1
    //
    // This works because one increment can be done by increasing a single integer by 2 (overshoot) or by 
    // increasing two integers by one. And the parity mismatch means one extra operation is needed for the leftover increment.

    if sum % 2 == 0 {
        sum / 2
    } else {
        sum / 2 + 1
    }
}